-- Arreglos a la página II (11-11-2026). Ejecutar una vez en el editor SQL de Supabase (proyecto BKO).
-- Fusiona solo los campos modificados; conserva el resto de lo editado desde el CMS.
begin;

-- Equipo: orden y textos de Roxana, Fenella y Estefanía.
update public.bko_content set sort_order=10 where id='jorge-ivan-saavedra-bentjerodt';
update public.bko_content set sort_order=20 where id='camila-alejandra-kopplin-lanata';
update public.bko_content set sort_order=30, data = data || '{"intro":"Profesional especializada en financiamiento de proyectos, negocios y seguros corporativos, con un enfoque de asesoría a empresas y personas de los sectores minero, marítimo, de la construcción y comercial.\n\nEspecialista en intermediación para vincular a pequeñas y medianas empresas con agentes financiadores. Su labor facilita la búsqueda de financiamiento, el diálogo entre las partes y apoya la presentación de necesidades de inversión y la búsqueda de alternativas, especialmente para adquirir maquinaria o desarrollar proyectos, de acuerdo con las características y los objetivos de cada iniciativa.\n\nDesde BKO, lidera el desarrollo del área de seguros y financiamiento, orientando a sus clientes en la identificación de coberturas acordes con su actividad económica. Su asesoría abarca garantías y licitaciones, responsabilidad civil, seguros para empresas, protección de maquinaria, seguros de vida y soluciones para actividades mineras, marítimas y comerciales."}'::jsonb where id='roxana-ximena-oyarzun-bustamante';
update public.bko_content set sort_order=40 where id='luis-miranda-chavarria';
update public.bko_content set sort_order=50, data = data || '{"intro":"La Dra. Fenella Reyes Gonzalo es Médico Cirujano por la Universidad de Santiago de Chile y especialista certificada en Psiquiatría Pediátrica y de la Adolescencia por la misma universidad. Complementa su formación con estudios de posgrado en otras instituciones. Entre ellos se encuentran el Diplomado en Destrezas Clínicas en Adicciones de la Pontificia Universidad Católica de Chile y el Diplomado en Apego y Psicopatología del Desarrollo del Centro de Apego y Regulación Emocional (CARE) de la Universidad del Desarrollo.\n\nA lo largo de su trayectoria ha profundizado especialmente en el abordaje del trauma y sus manifestaciones en niños, niñas y adolescentes. En este ámbito, ha incorporado formación y entrenamiento en EMDR (Eye Movement Desensitization and Reprocessing, o Desensibilización y Reprocesamiento por Movimientos Oculares). Este enfoque psicoterapéutico se utiliza en el abordaje de experiencias traumáticas y recuerdos perturbadores. Su formación incluye entrenamiento en protocolos EMDR para atención temprana y estrés traumático continuo, así como en EMDR y habilidades parentales.\n\nEsta preparación se complementa con formación en terapia cognitivo-conductual, intervención temprana, microanálisis y videofeedback, terapia de juego infantil y neurodesarrollo, configurando una mirada especializada sobre la salud mental infantojuvenil y los múltiples factores que pueden incidir en el desarrollo y bienestar de niños, niñas y adolescentes.\n\nSu intervención en el Estudio se concentra especialmente en casos de alta complejidad, particularmente en aquellos relacionados con el ámbito proteccional y con situaciones de vulneración de derechos de niños, niñas y adolescentes, en los que la naturaleza de los antecedentes hace relevante incorporar una perspectiva médica y psiquiátrica especializada al análisis del caso.\n\nEn estas situaciones, la Dra. trabaja de manera coordinada con el equipo jurídico y social, incorporando la perspectiva médico-psiquiátrica infantojuvenil a un abordaje interdisciplinario que considera conjuntamente las dimensiones médicas, de salud mental, familiares, jurídicas y psicosociales presentes en cada situación.\n\nSu participación adquiere especial relevancia en aquellos casos en los que resulta necesario comprender cómo determinados procesos traumáticos, condiciones de salud mental, elementos del desarrollo o circunstancias familiares y psicosociales pueden estar incidiendo en la situación del niño, niña o adolescente.\n\nDe esta manera, el trabajo interdisciplinario permite abordar los casos de mayor complejidad desde una perspectiva más amplia e integrada, articulando el análisis jurídico y social con el conocimiento especializado de la psiquiatría infantojuvenil, y situando las necesidades, el bienestar y las circunstancias particulares de cada niño, niña o adolescente como centro de la intervención."}'::jsonb where id='fenella-reyes-gonzalo';
update public.bko_content set sort_order=60 where id='makarena-andrea-ponce-villarroel';
update public.bko_content set sort_order=70, data = data || '{"role":"Asistente contable | Gestión de CAUCE","intro":"Estefanía es asistente contable de BKO y está a cargo de la gestión de CAUCE Gestión Integral, el sistema de la oficina para organizar y dar seguimiento documental a las carteras de cobranza. Su labor comprende la organización y revisión de antecedentes comerciales y contables, la conciliación de pagos y el seguimiento de saldos, identificando inconsistencias y documentación pendiente. Asimismo, apoya la preparación de expedientes para su evaluación por el área jurídica, contribuyendo a mantener información ordenada, respaldada y trazable durante las distintas etapas del proceso de recuperación.","specialties":["Asistencia contable","Gestión de CAUCE"],"areas":[]}'::jsonb where id='estefania-benitez-garcia';

-- Negocios y Seguros: nuevo orden, minería, seguros generales, fotos marítimas y presentación de Roxana.
update public.site_content set value = value || '{"groups":[{"id":"mineria","title":"Seguros para la minería","description":"Protección para faenas, contratistas, maquinaria y operaciones vinculadas a la actividad minera del norte de Chile.","note":"Las coberturas exigidas dependen de los contratos, reglamentos y estándares de cada mandante minero; se evalúan según la operación y la aceptación de la aseguradora."},{"id":"maritimos","note":"Las coberturas se evalúan según el uso, las características de la embarcación, la operación y la aceptación de la aseguradora.","title":"Seguros marítimos y embarcaciones","description":"Orientación conectada con la presencia de BKO en Puerto Varas y su área marítima y naviera."},{"id":"garantias","note":"Alternativas de garantías que pueden ayudar a optimizar el uso de las líneas de crédito bancarias de las empresas. La aceptación del instrumento depende de las bases de licitación, el contrato y las condiciones del beneficiario.","title":"Garantías y seguros para licitaciones","description":"Facilitamos el acceso a garantías para que tu empresa pueda participar y ejecutar nuevos proyectos."},{"id":"constructoras","note":"La exigencia de seguros depende de las bases de licitación, los contratos y los mandantes; no todos los seguros son obligatorios en todas las obras.","title":"Seguros para empresas constructoras","description":"Protección para obras, maquinaria, trabajadores y contratos."},{"id":"responsabilidad-civil","note":"","title":"Responsabilidad Civil — Protección para empresas","description":"Los riesgos asociados a las actividades empresariales pueden generar daños a terceros y responsabilidades económicas. Contar con una cobertura adecuada permite enfrentar estas contingencias de acuerdo con las condiciones de la póliza contratada."},{"id":"generales","title":"Seguros generales","description":"Protección personal, familiar y empresarial: seguros de vida, ahorro previsional, cesantía, protección de pagos y beneficios para trabajadores.","note":"Los beneficios tributarios del APV dependen del régimen elegido y de la normativa vigente. No se garantiza rentabilidad ni un beneficio tributario individual. El Seguro de Cesantía obligatorio administrado por AFC es un sistema legal de protección social; no es un producto comercial ofrecido por BKO. Los seguros complementarios son productos distintos y están sujetos a sus propias condiciones."}],"services":[{"id":"rc-general","cta":"SOLICITAR ASESORÍA","group":"responsabilidad-civil","image":"","order":0,"risks":["Accidentes de clientes o visitantes","Daños materiales a terceros","Incidentes relacionados con operaciones comerciales"],"title":"Responsabilidad Civil General","active":true,"category":"Responsabilidad Civil","imageAlt":"","description":"Cobertura de daños corporales y materiales causados a terceros como consecuencia de la actividad de una empresa, conforme a las condiciones y exclusiones de la póliza.","informational":false},{"id":"rc-empresas","cta":"SOLICITAR ASESORÍA","group":"responsabilidad-civil","image":"assets/oficinas/santiago/WhatsApp%20Image%202026-11-05%20at%2022.48.40.jpeg","order":1,"risks":["Predios y operaciones","Productos","Contratistas y subcontratistas","Actividades empresariales"],"title":"Responsabilidad Civil para Empresas","active":true,"category":"Seguros Empresariales","imageAlt":"Sala de reuniones de la oficina BKO en Santiago","description":"Soluciones para empresas de distintos tamaños y actividades económicas.","informational":false},{"id":"rc-profesional","cta":"SOLICITAR ASESORÍA","group":"responsabilidad-civil","image":"","order":2,"risks":["Abogados","Arquitectos e ingenieros","Contadores y consultores"],"title":"Responsabilidad Civil Profesional","active":true,"category":"Responsabilidad Civil","imageAlt":"","description":"Orientada a profesionales y empresas que prestan servicios especializados. Considera reclamaciones derivadas de errores u omisiones profesionales, de acuerdo con los términos contratados.","informational":false},{"id":"rc-cruzada","cta":"SOLICITAR ASESORÍA","group":"responsabilidad-civil","image":"","order":3,"risks":["Proyectos con múltiples participantes","Reclamaciones entre asegurados"],"title":"Responsabilidad Civil Cruzada","active":true,"category":"Responsabilidad Civil","imageAlt":"","description":"Especialmente relevante en construcción y proyectos con distintas empresas. Permite contemplar reclamaciones entre asegurados bajo las condiciones específicas de la póliza.","informational":false},{"id":"rc-patronal","cta":"SOLICITAR ASESORÍA","group":"responsabilidad-civil","image":"","order":4,"risks":["Reclamaciones por accidentes laborales"],"title":"Responsabilidad Civil Patronal","active":true,"category":"Responsabilidad Civil","imageAlt":"","description":"Cobertura relacionada con reclamaciones de responsabilidad civil derivadas de accidentes laborales sufridos por trabajadores, conforme a los términos y condiciones contratados.","informational":false},{"id":"rc-contaminacion","cta":"SOLICITAR ASESORÍA","group":"responsabilidad-civil","image":"","order":5,"risks":["Incidentes que puedan afectar suelos","Daños a recursos hídricos"],"title":"Responsabilidad Civil por Contaminación","active":true,"category":"Responsabilidad Civil","imageAlt":"","description":"Soluciones para riesgos relacionados con contaminación y daños ambientales, según el alcance de la cobertura.","informational":false},{"id":"todo-riesgo","cta":"SOLICITAR ASESORÍA","group":"constructoras","image":"","order":6,"risks":["Incendio","Sismo, cuando esté contemplado","Robo de materiales, según condiciones","Daños por agua","Daños accidentales durante la construcción","Otros riesgos contemplados en la póliza"],"title":"Todo Riesgo Construcción","active":true,"category":"Construcción","imageAlt":"","description":"Coberturas para proyectos durante su ejecución. Los siguientes riesgos son posibles riesgos asegurables, sujetos a las condiciones de la póliza.","informational":false},{"id":"rc-construccion","cta":"SOLICITAR ASESORÍA","group":"constructoras","image":"","order":7,"risks":["Daños a propiedades colindantes y vecinos","Accidentes de transeúntes","Caída de materiales","Daños derivados de excavaciones"],"title":"Responsabilidad Civil Construcción","active":true,"category":"Construcción","imageAlt":"","description":"Protección frente a reclamaciones por daños a terceros durante la ejecución de obras.","informational":false},{"id":"equipos","cta":"SOLICITAR ASESORÍA","group":"constructoras","image":"assets/oficinas/calama/WhatsApp%20Image%202026-11-05%20at%2022.51.17.jpeg","order":8,"risks":["Retroexcavadoras y grúas","Camiones y generadores","Equipos industriales","Maquinaria de construcción"],"title":"Equipos y Maquinaria","active":true,"category":"Maquinaria","imageAlt":"Vehículo de servicios industriales junto al acceso de BKO en Calama","description":"Soluciones que pueden considerar daños propios, robo y responsabilidad civil asociada, según cada producto.","informational":false},{"id":"accidentes-obras","cta":"SOLICITAR ASESORÍA","group":"constructoras","image":"","order":9,"risks":["Muerte accidental, cuando esté contemplada","Invalidez, según el seguro contratado"],"title":"Accidentes Personales para Trabajadores","active":true,"category":"Construcción","imageAlt":"","description":"Alternativas de protección complementaria para trabajadores de proyectos y faenas.","informational":false},{"id":"seriedad","cta":"SOLICITAR ASESORÍA","group":"garantias","image":"","order":10,"risks":["Participación en licitaciones","Compromiso del oferente"],"title":"Garantía de Seriedad de la Oferta","active":true,"category":"Licitaciones y Garantías","imageAlt":"","description":"Instrumentos destinados a respaldar el compromiso del oferente durante un proceso de licitación.","informational":false},{"id":"fiel-cumplimiento","cta":"SOLICITAR ASESORÍA","group":"garantias","image":"","order":11,"risks":["Ejecución de contratos","Obligaciones frente al beneficiario"],"title":"Garantía de Fiel Cumplimiento","active":true,"category":"Licitaciones y Garantías","imageAlt":"","description":"Garantías destinadas a respaldar el cumplimiento de las obligaciones contractuales.","informational":false},{"id":"correcta-ejecucion","cta":"SOLICITAR ASESORÍA","group":"garantias","image":"","order":12,"risks":["Obligaciones posteriores a la obra","Condiciones de las bases y contratos"],"title":"Garantía de Correcta Ejecución","active":true,"category":"Licitaciones y Garantías","imageAlt":"","description":"Soluciones relacionadas con obligaciones posteriores a la ejecución de obras, incluyendo los mecanismos de garantía establecidos en las bases y contratos.","informational":false},{"id":"seguro-garantia","cta":"SOLICITAR ASESORÍA","group":"garantias","image":"","order":13,"risks":["Evaluación de alternativas de garantías","Uso de líneas de crédito bancarias"],"title":"Seguro de Garantía","active":true,"category":"Licitaciones y Garantías","imageAlt":"","description":"Un seguro de garantía es emitido por una compañía aseguradora y se rige por las condiciones de su póliza. Una boleta bancaria es emitida por un banco. Son instrumentos distintos: el seguro no equivale jurídicamente a una boleta bancaria en todos los casos y su aceptación debe revisarse en cada licitación y contrato.","informational":false},{"id":"vida-ahorro","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":14,"risks":["Protección familiar","Acumulación de ahorro sujeta al producto"],"title":"Seguro de Vida con Ahorro","active":true,"category":"Vida y Ahorro","imageAlt":"","description":"Protección por fallecimiento junto con una alternativa de acumulación de ahorro, según las condiciones del producto.","informational":false},{"id":"apv","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":15,"risks":["Complementar el ahorro previsional","Evaluación del régimen tributario"],"title":"APV — Ahorro Previsional Voluntario","active":true,"category":"APV","imageAlt":"","description":"Alternativas de ahorro previsional voluntario para complementar la jubilación. Los regímenes tributarios tienen tratamientos distintos al aportar y al retirar; sus beneficios dependen de la elección y de la normativa vigente.","informational":false},{"id":"vida-temporal","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":16,"risks":["Protección por fallecimiento durante el período contratado"],"title":"Seguro de Vida Temporal","active":true,"category":"Vida y Ahorro","imageAlt":"","description":"Protección económica por un período determinado para personas y familias que necesitan respaldo financiero.","informational":false},{"id":"afc","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":17,"risks":["Consultar afiliación y beneficios directamente en AFC"],"title":"Seguro de Cesantía Obligatorio — AFC","active":true,"category":"Cesantía","imageAlt":"","description":"Sistema legal de protección económica ante la cesantía para las personas trabajadoras comprendidas por la normativa chilena, administrado por AFC y sujeto a requisitos legales de acceso. Información referencial: BKO no comercializa este sistema.","informational":true},{"id":"cesantia-complementaria","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":18,"risks":["Respaldo económico ante desempleo cubierto"],"title":"Seguro de Cesantía Complementario","active":true,"category":"Cesantía","imageAlt":"","description":"Alternativas de protección financiera frente a situaciones de desempleo, conforme al producto y sus requisitos.","informational":false},{"id":"pagos","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":19,"risks":["Cuotas y obligaciones financieras elegibles"],"title":"Protección de Pagos","active":true,"category":"Cesantía","imageAlt":"","description":"Soluciones asociadas a determinados créditos y obligaciones financieras que pueden cubrir cuotas durante períodos de cesantía, conforme a los términos contratados.","informational":false},{"id":"colectivos","cta":"SOLICITAR ASESORÍA","group":"generales","image":"","order":20,"risks":["Beneficios para equipos de trabajo","Condiciones de adhesión y cobertura"],"title":"Seguros Colectivos","active":true,"category":"Seguros Empresariales","imageAlt":"","description":"Alternativas de protección para trabajadores como parte de los beneficios empresariales, cuando exista un producto adecuado.","informational":false},{"id":"casco","cta":"SOLICITAR ASESORÍA","group":"maritimos","image":"assets/seguros/maritimo/marina-embarcaciones.jpeg","order":21,"risks":["Incendio y colisión","Varadura y robo","Daños derivados de eventos cubiertos"],"title":"Casco y Maquinaria de Embarcaciones","active":true,"category":"Embarcaciones","imageAlt":"Marina con yates y veleros amarrados en aguas del sur de Chile","description":"Alternativas de cobertura para embarcaciones y su maquinaria, sujetas a los eventos cubiertos por la póliza.","informational":false},{"id":"rc-maritima","cta":"SOLICITAR ASESORÍA","group":"maritimos","image":"assets/seguros/maritimo/puerto-carga.jpeg","order":22,"risks":["Daños a terceros vinculados a la operación marítima"],"title":"Responsabilidad Civil Marítima","active":true,"category":"Responsabilidad Civil Marítima","imageAlt":"Naves atracadas junto a un recinto portuario con carga","description":"Protección frente a reclamaciones por daños a otras embarcaciones, instalaciones portuarias o personas, de acuerdo con la póliza.","informational":false},{"id":"accidentes-bordo","cta":"SOLICITAR ASESORÍA","group":"maritimos","image":"assets/seguros/maritimo/muelle-pesquero.jpeg","order":23,"risks":["Tripulantes","Pasajeros"],"title":"Accidentes Personales para Tripulantes y Pasajeros","active":true,"category":"Embarcaciones","imageAlt":"Muelle con embarcaciones pesqueras y pasarela de acceso","description":"Alternativas de cobertura para personas a bordo, según las condiciones contratadas.","informational":false},{"id":"trabajo-maritimo","cta":"SOLICITAR ASESORÍA","group":"maritimos","image":"assets/seguros/maritimo/astillero.jpeg","order":24,"risks":["Pesca","Turismo","Transporte","Actividades comerciales"],"title":"Embarcaciones de Trabajo","active":true,"category":"Embarcaciones","imageAlt":"Astillero con grúa, pontones y embarcaciones de trabajo","description":"Soluciones según el uso y actividad comercial de cada embarcación.","informational":false},{"id":"rc-minera","cta":"SOLICITAR ASESORÍA","group":"mineria","image":"","order":25,"risks":["Contratistas y subcontratistas de la minería","Daños a instalaciones del mandante","Daños a terceros durante la operación"],"title":"Responsabilidad Civil para Faenas Mineras","active":true,"category":"Responsabilidad Civil","imageAlt":"","description":"Cobertura frente a reclamaciones de terceros derivadas de trabajos y servicios ejecutados en faenas mineras, conforme a las condiciones y exclusiones de la póliza.","informational":false},{"id":"equipos-mineros","cta":"SOLICITAR ASESORÍA","group":"mineria","image":"","order":26,"risks":["Camiones y equipos de carguío","Maquinaria de movimiento de tierra","Equipos de perforación y apoyo"],"title":"Equipos y Maquinaria Minera","active":true,"category":"Maquinaria","imageAlt":"","description":"Alternativas de cobertura para maquinaria pesada y equipos móviles utilizados en faena, que pueden considerar daños propios, robo y responsabilidad civil según cada producto.","informational":false},{"id":"accidentes-faena","cta":"SOLICITAR ASESORÍA","group":"mineria","image":"","order":27,"risks":["Muerte accidental, cuando esté contemplada","Invalidez, según el seguro contratado","Gastos médicos, según condiciones"],"title":"Accidentes Personales para Trabajadores de Faena","active":true,"category":"Seguros Empresariales","imageAlt":"","description":"Protección complementaria para trabajadores que se desempeñan en faenas mineras y servicios asociados, según el seguro contratado.","informational":false},{"id":"garantias-mineras","cta":"SOLICITAR ASESORÍA","group":"mineria","image":"","order":28,"risks":["Licitaciones con mandantes mineros","Contratos de servicios y obras"],"title":"Garantías para Contratos Mineros","active":true,"category":"Licitaciones y Garantías","imageAlt":"","description":"Garantías de seriedad de la oferta y de fiel cumplimiento exigidas en licitaciones y contratos con compañías mineras, sujetas a las bases de cada mandante.","informational":false},{"id":"transporte-carga","cta":"SOLICITAR ASESORÍA","group":"mineria","image":"","order":29,"risks":["Transporte terrestre de insumos","Traslado de maquinaria"],"title":"Transporte de Insumos y Equipos","active":true,"category":"Seguros Empresariales","imageAlt":"","description":"Coberturas para el traslado de insumos, equipos y materiales hacia y desde las faenas, según las condiciones del seguro.","informational":false}],"highlights":["Seguros para la minería","Seguros marítimos","Garantías y licitaciones","Empresas constructoras","Responsabilidad Civil","Seguros generales"],"roxana":{"name":"Roxana Ximena Oyarzún Bustamante","role":"Experta en Negocios y Seguros Corporativos | Encargada del Área de Seguros BKO","image":"assets/personas/roxana-367.webp","description":"Profesional especializada en financiamiento de proyectos, negocios y seguros corporativos, con un enfoque de asesoría a empresas y personas de los sectores minero, marítimo, de la construcción y comercial.\n\nEspecialista en intermediación para vincular a pequeñas y medianas empresas con agentes financiadores. Su labor facilita la búsqueda de financiamiento, el diálogo entre las partes y apoya la presentación de necesidades de inversión y la búsqueda de alternativas, especialmente para adquirir maquinaria o desarrollar proyectos, de acuerdo con las características y los objetivos de cada iniciativa.\n\nDesde BKO, lidera el desarrollo del área de seguros y financiamiento, orientando a sus clientes en la identificación de coberturas acordes con su actividad económica. Su asesoría abarca garantías y licitaciones, responsabilidad civil, seguros para empresas, protección de maquinaria, seguros de vida y soluciones para actividades mineras, marítimas y comerciales.","specialties":["Responsabilidad Civil","Seguros para empresas","Seguros para constructoras","Garantías para licitaciones","Seguros de maquinaria","Seguros de vida y ahorro","Protección de pagos","Seguros marítimos y embarcaciones"]}}'::jsonb where key='insurance';

